<map version="1.0.1"><node CREATED="1747229335877" ID="ID_root" MODIFIED="1747229335877" TEXT="指针基础&amp;amp;指针与数组"><node CREATED="1747229335877" ID="ID_7a009eabddb45029" POSITION="right" MODIFIED="1747229335877" TEXT="前置准备知识"><node CREATED="1747229335877" ID="ID_7d2e00e6c3435831" MODIFIED="1747229335877" TEXT="虚拟内存"><node CREATED="1747229335877" ID="ID_14186b18cac9f999" MODIFIED="1747229335877" TEXT="把面试不要当笔试。&amp;nbsp;&amp;lt;br&amp;gt;一些东西懂，&amp;nbsp;但是一定要会用自己的语言组织出来。&amp;nbsp;&amp;lt;br&amp;gt;背面经的更高境界，应该是用自己的话把这些知识点答出来。然后又让别人感觉到你不是背出来的，是用自己的话答出来的。&amp;nbsp;"></node><node CREATED="1747229335877" ID="ID_bf41e2a18b248308" MODIFIED="1747229335877" TEXT="先大后小（先说整体的概念，然后再答里面的细节）&amp;lt;br&amp;gt;虚拟内存，是一个虚拟的内存。我们认为程序中得到的内存，都是虚拟内存，我们拿到的内存都是连续的，从0开始的。&amp;lt;br&amp;gt;如果直接使用物理内存，进程隔离过于困难。&amp;nbsp;&amp;lt;br&amp;gt;内存碎片，非常麻烦&amp;lt;br&amp;gt;程序员直接控制物理内存麻烦。&amp;nbsp;"></node></node><node CREATED="1747229335877" ID="ID_b6bee6b1b7df77ad" MODIFIED="1747229335877" TEXT="内存地址"><node CREATED="1747229335877" ID="ID_f1aa5d17c40e589c" MODIFIED="1747229335877" TEXT="内存地址就是内存上一个地址的唯一标识。&amp;nbsp;用数组的下标来类比。"></node><node CREATED="1747229335877" ID="ID_e3f26b74bf1f407e" MODIFIED="1747229335877" TEXT="在32位系统应用程序中，&amp;nbsp;位置标识32位，也即32个0和1.但是太长了，我们把它转换为16进制，用8个16进制数来表示"></node><node CREATED="1747229335877" ID="ID_e571000e0fe79e69" MODIFIED="1747229335877" TEXT="64位下，64个0和1,16个16进制数。"></node></node><node CREATED="1747229335877" ID="ID_56a88a48d7196c17" MODIFIED="1747229335877" TEXT="变量地址"><node CREATED="1747229335877" ID="ID_1d4761cbe6f77942" MODIFIED="1747229335877" TEXT="变量也有地址，在C中，其实就是我们所说的指针，有一些类型，比如int，有4个字节。这时候需要存储下来这个地址，采用的方式是存储首地址。"></node><node CREATED="1747229335877" ID="ID_ec381255d5ff05e5" MODIFIED="1747229335877" TEXT="比如一个int，占用 1 2 3 4&amp;nbsp;四个字节的位置。&amp;nbsp;但是存储它的地址是，是存储的首字节，即1这个字节。"></node></node><node CREATED="1747229335877" ID="ID_9256baa75db10417" MODIFIED="1747229335877" TEXT="变量的数据如何存储在内存上的"><node CREATED="1747229335878" ID="ID_47f2f8163333decb" MODIFIED="1747229335878" TEXT="比如一个int,占用四个字节。这四个字节是需要存储到内存上的，采用的是小端存储法"></node><node CREATED="1747229335878" ID="ID_334e99cd6c78500c" MODIFIED="1747229335878" TEXT="也就是数据的低位，存储到内存的低位上去。&amp;nbsp;"></node><node CREATED="1747229335878" ID="ID_1503898f979e45aa" MODIFIED="1747229335878" TEXT="小端存储法和大端存储法：&amp;nbsp;数据在内存上的存储方式"></node></node></node><node CREATED="1747229335878" ID="ID_f4d1cc84023884a5" POSITION="right" MODIFIED="1747229335878" TEXT="指针变量"><node CREATED="1747229335878" ID="ID_095efead2159ec43" MODIFIED="1747229335878" TEXT="指针：&amp;nbsp;就是存储的地址"></node><node CREATED="1747229335878" ID="ID_a9847fba09010b48" MODIFIED="1747229335878" TEXT="指针变量：&amp;nbsp;这个地址需要存储下来，这个就是指针变量。也就是一个变量专门用于存储指针，这个变量也是需要存储在内存上的。"></node><node CREATED="1747229335878" ID="ID_5bc5d9d5354d0fb6" MODIFIED="1747229335878" TEXT="这里自己需要画图理解一下指针变量。"><node CREATED="1747229335878" ID="ID_fd8e75bab9c82742" MODIFIED="1747229335878" TEXT="其实平时我们就用指针就可以，但是理解这个指针、指针变量、&amp;lt;br&amp;gt;指针变量的内存。其实可以帮助我们更深入的理解指针是什么东西"></node></node></node><node CREATED="1747229335878" ID="ID_fe629ddb1d7c89ed" POSITION="right" MODIFIED="1747229335878" TEXT="指针变量的使用"><node CREATED="1747229335878" ID="ID_7b3ab3cdc661920d" MODIFIED="1747229335878" TEXT="声明"><node CREATED="1747229335878" ID="ID_22e0b081c482fe73" MODIFIED="1747229335878" TEXT="数据类型 *指针名;"></node><node CREATED="1747229335878" ID="ID_d38692e7536f29bc" MODIFIED="1747229335878" TEXT="int *p; //&amp;nbsp;推荐&amp;lt;br&amp;gt;int* p; //&amp;nbsp;不推荐"></node><node CREATED="1747229335878" ID="ID_bcadd0a19208da5e" MODIFIED="1747229335878" TEXT="int* p1, p2,p3;&amp;lt;br&amp;gt;原因是可能造成一些困惑"></node><node CREATED="1747229335878" ID="ID_f857cd88685c3a6a" MODIFIED="1747229335878" TEXT="顺便讲了一下C的&amp;nbsp;声明风格问题&amp;lt;br&amp;gt;"><node CREATED="1747229335878" ID="ID_829cb90f0223692e" MODIFIED="1747229335878" TEXT="一个比较好的变量声明方式。&amp;nbsp;&amp;lt;br&amp;gt;数据类型&amp;nbsp;变量名;&amp;lt;br&amp;gt;&amp;lt;br&amp;gt;int[10]&amp;nbsp; arr;"></node></node><node CREATED="1747229335878" ID="ID_f6bf1ae0ae11cef8" MODIFIED="1747229335878" TEXT="声明的注意点"><node CREATED="1747229335878" ID="ID_f227db322d65e13e" MODIFIED="1747229335878" TEXT="数据类型 *变量名;&amp;lt;br&amp;gt;char ch = &amp;apos;a&amp;apos;;&amp;lt;br&amp;gt;int *p_num = &amp;amp;ch;&amp;lt;br&amp;gt;指针指向的类型一定要是这个类型。如果用另外一个类型来指向这种类型，未定义行为。&amp;nbsp;&amp;nbsp;"></node></node></node><node CREATED="1747229335878" ID="ID_647aa11966293094" MODIFIED="1747229335878" TEXT="初始化"><node CREATED="1747229335878" ID="ID_b42a9ceed72a2036" MODIFIED="1747229335878" TEXT="如果只声明，不初始化，这时候指针里面的值是随机的，如果直接用，访问到的可能是一个随机的地方。有可能访问到垃圾值，有可能访问到别的函数里的值，有可能导致程序崩溃。&amp;lt;br&amp;gt;所以需要对其初始化"></node><node CREATED="1747229335878" ID="ID_e941708ae2c1303f" MODIFIED="1747229335878" TEXT="初始化方式"><node CREATED="1747229335878" ID="ID_2c20bee2d8edeb36" MODIFIED="1747229335878" TEXT="1.直接用 &amp;amp;num，将num的地址取出给指针"></node><node CREATED="1747229335878" ID="ID_f7f8223cb0fe9bc9" MODIFIED="1747229335878" TEXT="2.用NULL赋值。NULL代表它不可用"></node><node CREATED="1747229335878" ID="ID_0ef714e0b014e01f" MODIFIED="1747229335878" TEXT="3.用其他指针赋值"><node CREATED="1747229335878" ID="ID_31e58145ca6c4ac2" MODIFIED="1747229335878" TEXT="int *p_num = arr;"></node></node></node></node><node CREATED="1747229335878" ID="ID_88a1caa6a15fbb01" MODIFIED="1747229335878" TEXT="两种比较特殊的指针"><node CREATED="1747229335878" ID="ID_a8a483edc3609e2b" MODIFIED="1747229335878" TEXT="野指针"><node CREATED="1747229335878" ID="ID_07ad1a24af929138" MODIFIED="1747229335878" TEXT="这个指针我们不知道指到了哪里"></node><node CREATED="1747229335878" ID="ID_fa7b53ae2c6a59a6" MODIFIED="1747229335878" TEXT="所以使用的时候，可能取出来废值，可能取出来了其他函数里的值，也可能会导致程序崩溃"></node><node CREATED="1747229335878" ID="ID_53eefaa037b21439" MODIFIED="1747229335878" TEXT="这个就是野指针"></node><node CREATED="1747229335878" ID="ID_fc693f0379f20878" MODIFIED="1747229335878" TEXT="野指针出现的多种情况"><node CREATED="1747229335878" ID="ID_3836c5fb42d3896f" MODIFIED="1747229335878" TEXT="指针没有初始化"></node><node CREATED="1747229335878" ID="ID_7333a4724c160a17" MODIFIED="1747229335878" TEXT="用一个int给指针赋值"></node><node CREATED="1747229335878" ID="ID_99354bf954f6316f" MODIFIED="1747229335878" TEXT="int *p_num = 666;"></node></node><node CREATED="1747229335878" ID="ID_5e48cb1262bc4761" MODIFIED="1747229335878" TEXT="关于野指针，一定要小心。我们应该避免使用野指针"></node></node><node CREATED="1747229335878" ID="ID_d3b3e105ba8e1e79" MODIFIED="1747229335878" TEXT="空指针"><node CREATED="1747229335878" ID="ID_4b97d319102b161b" MODIFIED="1747229335878" TEXT="给一个指针赋值为NULL。NULL其实就是一个特殊值：0"></node><node CREATED="1747229335878" ID="ID_16239ed59c8cf6ca" MODIFIED="1747229335878" TEXT="这个空地址，不能取值，也不能赋值。如果取值赋值、会崩溃"></node><node CREATED="1747229335878" ID="ID_fbbe329fddb9a1ac" MODIFIED="1747229335878" TEXT="使用指针之前，可以判断一下。如果是空指针，就不去解引用，不去赋值。"><node CREATED="1747229335878" ID="ID_8f2ae7708478b472" MODIFIED="1747229335878" TEXT="int *p_num = NULL;&amp;lt;br&amp;gt;*p_num;&amp;lt;br&amp;gt;if(p_num !=NULL){&amp;lt;br&amp;gt;//&amp;nbsp;再去操作&amp;lt;br&amp;gt;}"></node></node><node CREATED="1747229335878" ID="ID_d0a7dfa270e61ae0" MODIFIED="1747229335878" TEXT="空指针明确的告知，这个位置不能使用。"></node></node></node></node><node CREATED="1747229335878" ID="ID_5a36d0bbc0df6247" POSITION="right" MODIFIED="1747229335878" TEXT="值传递"><node CREATED="1747229335878" ID="ID_1a0609811168400f" MODIFIED="1747229335878" TEXT="如果传递一个指针的时候，也是值传递。就是将指针的值复制一份传过去。&amp;nbsp;&amp;lt;br&amp;gt;但是我们可以通过这个值，去改原数据。&amp;lt;br&amp;gt;"></node></node><node CREATED="1747229335878" ID="ID_81a93d8d4e404e20" POSITION="right" MODIFIED="1747229335878" TEXT="指针和数组"><node CREATED="1747229335878" ID="ID_a0c09e0a47ec4208" MODIFIED="1747229335878" TEXT="数组名是什么"><node CREATED="1747229335878" ID="ID_5aa67f4722696e45" MODIFIED="1747229335878" TEXT="数组名可以看做是一个指向数组连续空间的首地址，&amp;lt;br&amp;gt;在大多数情况下。数组名都可以看作是首指针使用"></node><node CREATED="1747229335878" ID="ID_1cbe63539a8cd7ed" MODIFIED="1747229335878" TEXT="数组名哪些场景可以看做是首指针"><node CREATED="1747229335878" ID="ID_9e4c4c2baa1dc2a6" MODIFIED="1747229335878" TEXT="给一个指针变量赋值的时候&amp;lt;br&amp;gt;int *p_num = arr;"></node><node CREATED="1747229335878" ID="ID_dd2447310c0bccc3" MODIFIED="1747229335878" TEXT="函数传参的时候"></node><node CREATED="1747229335878" ID="ID_016ebf36c5db2b88" MODIFIED="1747229335878" TEXT="算术运算的时候"></node></node><node CREATED="1747229335878" ID="ID_f53b915bab7d7859" MODIFIED="1747229335878" TEXT="哪些场景不能看做首指针"><node CREATED="1747229335878" ID="ID_e334685e6c747882" MODIFIED="1747229335878" TEXT="sizeof()&amp;nbsp;这时候不是当做指针，是当做整个数组来的&amp;lt;br&amp;gt;sizeof(arr)"></node><node CREATED="1747229335878" ID="ID_9802de829e3c217c" MODIFIED="1747229335878" TEXT="&amp;amp;运算符的时候，这时候拿到的也是一个数组指针"></node></node><node CREATED="1747229335878" ID="ID_e301abf0f6cbf8f0" MODIFIED="1747229335878" TEXT="两个很绕的概念"><node CREATED="1747229335878" ID="ID_979fb220874e2e46" MODIFIED="1747229335878" TEXT="数组指针和指针数组"><node CREATED="1747229335878" ID="ID_c6430f9ce8147c01" MODIFIED="1747229335878" TEXT="直接看后缀。后缀是什么就是什么"></node><node CREATED="1747229335878" ID="ID_6d1da43dd48e4e29" MODIFIED="1747229335878" TEXT="数组指针就是指针。&amp;nbsp;这个指针在偏移的时候，一次会偏移数组大小个空间"></node><node CREATED="1747229335878" ID="ID_9b1a96899ede69cc" MODIFIED="1747229335878" TEXT="指针数组就是数组。这个数组里面存储的都是指针"></node><node CREATED="1747229335878" ID="ID_9c1ad33fab6ba518" MODIFIED="1747229335878" TEXT="*&amp;nbsp;和 [] 。 []优先级高，&amp;nbsp;依据这个来认表达式是什么东西。&amp;nbsp;&amp;lt;br&amp;gt;中文很重要，但是更重要的是，见到了式子要知道这是啥东西"><node CREATED="1747229335878" ID="ID_70860e96534f98a4" MODIFIED="1747229335878" TEXT="int *p_arr[10];&amp;lt;br&amp;gt;[]优先级高，上来就决定了自己是数组。int *(其余的部分)说明是一个装指针的数组。&amp;nbsp;&amp;nbsp;"></node><node CREATED="1747229335878" ID="ID_aedc2a0fd0a42965" MODIFIED="1747229335878" TEXT="int (*p_arr2)[10];&amp;lt;br&amp;gt;这是指针。&amp;nbsp;这个指针指向长度为10的数组。"></node><node CREATED="1747229335878" ID="ID_798f2a0481036a10" MODIFIED="1747229335878" TEXT="char *ptr_str[10];&amp;lt;br&amp;gt;&amp;lt;br&amp;gt;"></node></node><node CREATED="1747229335878" ID="ID_b4ffdbb0c6d9397e" MODIFIED="1747229335878" TEXT="面试要会。&amp;lt;br&amp;gt;但是更重要的是写代码见到了会认，自己写会写"></node></node><node CREATED="1747229335878" ID="ID_34aa2b64317f39be" MODIFIED="1747229335878" TEXT="constant pointer &amp;amp; pointer to constant&amp;lt;br&amp;gt;指针常量和常量指针&amp;lt;br&amp;gt;"><node CREATED="1747229335878" ID="ID_13cf9a9c37265e8c" MODIFIED="1747229335878" TEXT="使用const来修饰指针。&amp;nbsp;这时候指针有一些无法被修改的情况&amp;lt;br&amp;gt;"></node><node CREATED="1747229335878" ID="ID_38af1571904fe2e0" MODIFIED="1747229335878" TEXT="const怎么记？&amp;nbsp; 整体修饰谁，谁就不能动"></node><node CREATED="1747229335878" ID="ID_ced38dc032403cf6" MODIFIED="1747229335878" TEXT="const int *p=&amp;amp;a;"></node><node CREATED="1747229335878" ID="ID_4045462caa23cd23" MODIFIED="1747229335878" TEXT="int * const p2 = &amp;amp;b;"></node><node CREATED="1747229335878" ID="ID_7c4c38ca3ca3eed6" MODIFIED="1747229335878" TEXT="前面的概念在面试的时候考，但是对于写代码，&amp;lt;br&amp;gt;需要注意的点是：&amp;nbsp;见到这个东西，要知道是啥意思，或者说谁不能改。"></node><node CREATED="1747229335878" ID="ID_cd14511cea700659" MODIFIED="1747229335878" TEXT="const int *const p4 = &amp;amp;a;&amp;lt;br&amp;gt;"></node></node></node></node><node CREATED="1747229335878" ID="ID_807fdbc962652f20" MODIFIED="1747229335878" TEXT="数组作为参数传递"><node CREATED="1747229335878" ID="ID_4958e8bd13c91890" MODIFIED="1747229335878" TEXT="在传递的过程中，会退化成首指针"></node><node CREATED="1747229335878" ID="ID_44c10c122bbdc516" MODIFIED="1747229335878" TEXT="在传参过程中，长度会被丢弃掉，我们在函数内部拿到的只有首指针。&amp;nbsp;&amp;lt;br&amp;gt;所以一般情况下，我们传递数组的时候，会顺便传递一个长度"></node><node CREATED="1747229335878" ID="ID_39671ed5394c40b8" MODIFIED="1747229335878" TEXT="传指针不是很麻烦，但是要注意的点是：&amp;nbsp;你传的指针，指针指的是一个地址。&amp;lt;br&amp;gt;需要注意的是，这块地址到底能不能用"></node></node><node CREATED="1747229335878" ID="ID_2f83ade6771352a4" MODIFIED="1747229335878" TEXT="指针的算术运算"><node CREATED="1747229335878" ID="ID_4049bea9bc707f38" MODIFIED="1747229335878" TEXT="可以进行加法"><node CREATED="1747229335878" ID="ID_b8d8ee5e38136ea5" MODIFIED="1747229335878" TEXT="加几，就是往后偏移几个内存单元。&amp;nbsp;比如是一个int类型的指针，+2。就是往后偏移两个int"></node><node CREATED="1747229335878" ID="ID_67c7cc6fce2d4aa0" MODIFIED="1747229335878" TEXT="matrix这个数组指针的偏移，需要自己再看一下"></node></node><node CREATED="1747229335878" ID="ID_051de82739e04f19" MODIFIED="1747229335878" TEXT="减法"></node><node CREATED="1747229335878" ID="ID_500bbc1e20d74026" MODIFIED="1747229335878" TEXT="自增和自减"><node CREATED="1747229335878" ID="ID_757258ea1d7f93e1" MODIFIED="1747229335878" TEXT="*p++&amp;nbsp;这个表达式一定要知道是什么意思&amp;lt;br&amp;gt;"></node></node></node><node CREATED="1747229335878" ID="ID_6818bd3c3ae0aecc" MODIFIED="1747229335878" TEXT="指针作为返回值&amp;lt;br&amp;gt;"><node CREATED="1747229335878" ID="ID_4b8d939a5ed75474" MODIFIED="1747229335878" TEXT="需要注意一下返回的指针的生命周期问题。不能返回的指针指向的内存，不能用了。这时候变成了我们所说的悬空指针。"><node CREATED="1747229335878" ID="ID_9652343b03b3d21d" MODIFIED="1747229335878" TEXT="悬空指针需要理解一下。&amp;nbsp;简单说就是一个指针，&amp;lt;br&amp;gt;之前指向一片有效内存，后面这片内存失效了，&amp;nbsp;这就是一个悬空指针&amp;lt;br&amp;gt;悬空指针是野指针的一种"></node></node><node CREATED="1747229335878" ID="ID_d877011a281fb4ec" MODIFIED="1747229335878" TEXT="永远不要返回当前栈区的内容。&amp;nbsp;因为当前栈区的数据，在函数调用结束之后，就会被清掉。&amp;nbsp;"></node><node CREATED="1747229335878" ID="ID_e168aa235ba921a4" MODIFIED="1747229335878" TEXT="在C里面，函数不允许返回数组。&amp;lt;br&amp;gt;我们可以用指针来等价替换。&amp;nbsp;"></node></node></node></node></map>